class Plane {

    void fly() {
        System.out.println("Plane is flying");
    }

    void land() {
        System.out.println("Plane is landing");
    }
}

class CargoPlane extends Plane {

    void land() {
        System.out.println("Cargo plane is landing on huge runway");
    }

    void carryCargo() {
        System.out.println("Cargo plane is carrying cargo");
    }
}

void land() {
    System.out.println("Cargo plane is landing on huge runway");
}

class PassengerPlane extends Plane {

    void land() {
        System.out.println("Passenger plane is landing on medium sized runway");
    }

    void carryPassenger() {
        System.out.println("Passenger plane is carrying passengers");
    }
}

CargoPlane cp = new CargoPlane();

cp.fly();
cp.carryCargo();
cp.land();

PassengerPlane pp = new PassengerPlane();

pp.fly();
pp.carryPassenger();
pp.land();

